content:
@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-base-warm-50);
    box-shadow: var(--shelf-shadow-md);
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    color: var(--shelf-fgColor-default);
    box-shadow: var(--shelf-shadow-md);
  }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background: var(--shelf-chip-bgColor);
    box-shadow: var(--shelf-shadow-md);
  }
}

@layer tokens {
  :root {
    --shelf-base-warm-50: hsl(30 15% 97%);
    --shelf-base-warm-900: hsl(16 12% 10%);
    --shelf-chip-bgColor: var(--shelf-base-warm-50);
    --shelf-bgColor-default: var(--shelf-base-warm-50);
    --shelf-fgColor-default: var(--shelf-base-warm-900);
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body {
    margin: 0;
    background-color: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
  }
}

@layer components {
  .shelf-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
    gap: var(--shelf-space-md);
    padding: var(--shelf-space-lg);
  }
}

@layer components {
  .shelf-grid-skeleton {
    inline-size: var(--shelf-skeleton-width);
    block-size: var(--shelf-space-2xl);
    border-radius: var(--shelf-radius-md);
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    background-color: var(--shelf-bgColor-raised);
    color: var(--shelf-fgColor-default);
    box-shadow: var(--shelf-shadow-lg);
    border-radius: var(--shelf-radius-lg);
    padding: var(--shelf-space-lg);
  }
}
